import { SeedTsPaginationUriPathParamsClient } from "@fern/ts-pagination-uri-path-params";

const client = new SeedTsPaginationUriPathParamsClient({ environment: "YOUR_BASE_URL", token: "YOUR_TOKEN" });
const pageableResponse = await client.users.listWithUriPagination({
    "X-Api-Version": "X-Api-Version",
    accountId: "accountId",
    pageSize: 1
});
for await (const item of pageableResponse) {
    console.log(item);
}

// Or you can manually iterate page-by-page
let page = await client.users.listWithUriPagination({
    "X-Api-Version": "X-Api-Version",
    accountId: "accountId",
    pageSize: 1
});
while (page.hasNextPage()) {
    page = page.getNextPage();
}

// You can also access the underlying response
const response = page.response;

